r = primitives.call(name='inspect_cliport_instances')
print('ok', r.ok)
o = r.output
if isinstance(o, dict):
    print('keys', list(o.keys()))
    insts = o.get('instances', [])
    if isinstance(insts, list) and len(insts) > 0 and isinstance(insts[0], dict):
        print('inst_keys', list(insts[0].keys()))
    for i in insts:
        if isinstance(i, dict):
            print(i.get('object_id'), i.get('mean_rgb'), i.get('pose0'), i.get('size_xyz'), i.get('evidence_id'))
        else:
            print(str(i)[:300])
else:
    print(str(o)[:3000])

pose_by_id = {}
for i in insts:
    pose_by_id[i.get('object_id')] = i.get('pose0')
for oid, d in [(6, -0.03), (7, 0.03)]:
    rr = primitives.call(name='inspect_cliport_instance', object_id=oid)
    if not rr.ok:
        print('inspect fail', oid, str(rr.output)[:300]); continue
    out = rr.output
    print(oid, 'keys', list(out.keys()) if isinstance(out, dict) else type(out))
    p = None
    if isinstance(out, dict):
        p = out.get('pose0')
        if p is None and isinstance(out.get('instance'), dict):
            p = out['instance'].get('pose0')
    if p is None:
        p = pose_by_id[oid]
    pick = [[p[0][0], p[0][1], p[0][2]], [0, 0, 0, 1]]
    place = [[bx + d*ux, by + d*uy, 0.03], q]
    a = primitives.call(name='submit_cliport_pick_place_action', pick_pose=pick, place_pose=place,
                        evidence_ids=[out.get('evidence_id'), box_ev], source_object_id=oid, target_object_id=5)
    print(oid, a.ok, str(a.output)[:500])
